ruleSearch.bookList:
@js:
var tabs = (JSON.parse(result).search_tabs) || [];
var out = [];
for (var t = 0; t < tabs.length; t++) {
  var tab = tabs[t];
  if (tab.tab_type !== 3) continue; // 只取书籍tab(纯小说)
  var data = tab.data || [];
  for (var i = 0; i < data.length; i++) {
    var cell = data[i];
    if (!cell) continue;
    var bd = cell.book_data;
    if (!bd) continue;
    var push = function(b) {
      if (b && b.book_name && String(b.book_type) === "0" && (b.author || "").indexOf("主播") < 0) {
        try { b.fq_url = fqTocUrl(String(b.book_id)); } catch (e) { b.fq_url = ""; }
        out.push(b);
      }
    };
    if (bd.length !== undefined) {
      for (var j = 0; j < bd.length; j++) push(bd[j]);
    } else if (typeof bd === "object") {
      push(bd);
    }
  }
}
out;

