    Math.floor(Math.random() * 0x7fffffff),
    Math.floor(Math.random() * 0x7fffffff),
    Math.floor(Math.random() * 0x7fffffff));
  hdrs["User-Agent"] = FQ_UA;
  hdrs["Accept"] = "application/json, text/plain, */*";
  var opt = {"method": method, "headers": hdrs};
  if (method === "POST" && bodyStr) opt["body"] = bodyStr;
  return url + "," + JSON.stringify(opt);
}

// 搜索(分页)
function fqSearchUrl(key, page){
  var p = parseInt(page, 10);
  if (isNaN(p) || p < 1) p = 1;
  var off = (p - 1) * 20;
  return fqSignedUrl("GET", "/reading/bookapi/search/tab/v:version/", [
    ["query", String(key || "")],
    ["tab_type", "3"],
    ["offset", String(off)],
    ["passback", String(off)],
    ["count", "20"]
  ], null);
}

// 详情+目录(init=data 复用同一响应)
function fqTocUrl(bookId){
  return fqSignedUrl("GET", "/reading/bookapi/directory/all_items/v:version/", [
    ["book_id", String(bookId)]
  ], null);
}

// 发现-分类分页(new_category/landing, offset=(page-1)*10)
function fqCategoryUrl(catId, gender, page){
  var p = parseInt(page, 10);
  if (isNaN(p) || p < 1) p = 1;
  var off = (p - 1) * 10;
  return fqSignedUrl("GET", "/reading/bookapi/new_category/landing/v:version/", [
    ["category_id", String(catId)],
    ["gender", String(gender)],
    ["offset", String(off)],
    ["page_size", "20"]
  ], null);
}

// 正文 batch_full
function fqContentUrl(bookId, itemId){
  return fqSignedUrl("GET", "/reading/reader/batch_full/v:version/", [
    ["book_id", String(bookId)],
    ["item_ids", String(itemId)]
  ], null);
}

// registerkey (POST 获取会话密钥)
function fqRegUrl(){
  var ivB = [];
  for (var i = 0; i < 16; i++) ivB.push(Math.floor(Math.random() * 256));
  var bodyStr = fqRegisterKeyBody(FQ_DEVICE_ID, ivB);
  var qs = fqRegQuery();
  var url = FQ_HOST + "/reading/crypt/registerkey?" + qs;
  var queryBytes = fqS2b(qs);
  var bodyBytes = fqS2b(bodyStr);
  var current = Math.floor(Date.now() / 1000);
  var khronos = fqPickKhronos(queryBytes, bodyBytes, current);
  var hdrs = fqMedusaHeaders(queryBytes, bodyBytes, FQ_DEVICE_ID, khronos,
    Math.floor(Math.random() * 0x7fffffff),
    Math.floor(Math.random() * 0x7fffffff),
    Math.floor(Math.random() * 0x7fffffff),
    Math.floor(Math.random() * 0x7fffffff));
  hdrs["User-Agent"] = FQ_UA;
  hdrs["Accept"] = "application/json, text/plain, */*";
  hdrs["Content-Type"] = "application/json; encoding=utf-8";
  return url + "," + JSON.stringify({"method":"POST","body":bodyStr,"headers":hdrs});
}

// 确保会话密钥(注册一次, 全局缓存)
function fqEnsureSessionKey(java){
  if (FQ_SESSION_KEY) return FQ_SESSION_KEY;
  var key = null;
  try {
    var resp = java.ajax(fqRegUrl());
    var j = JSON.parse(resp);
    key = fqUnwrapSessionKey((j.data && j.data.key) || "");
  } catch (e) { key = null; }
  if (key) FQ_SESSION_KEY = key;
  return key;
}


// ---------- HTML 正文 -> 纯文本 ----------
function fqHtmlUnescape(s){
  if (s.indexOf("&") < 0) return s;
  return s.replace(/&(?:#x([0-9a-fA-F]+)|#(\d+)|(lt|gt|amp|quot|apos|nbsp));/g, function(all, hx, dec, named){
    var c;
    if (hx) c = parseInt(hx, 16);
    else if (dec) c = parseInt(dec, 10);
    else if (named === "lt") c = 60;
    else if (named === "gt") c = 62;
    else if (named === "amp") c = 38;
    else if (named === "quot") c = 34;
    else if (named === "apos") c = 39;
    else if (named === "nbsp") c = 160;
    if (c === undefined || c === null) return all;
    return String.fromCharCode(c);
  });
}
function fqExtractText(xml){
  if (!xml) return "";
  var blocks = [];
  var re = /<blk[^>]*>([\s\S]*?)<\/blk>/g;
  var m;
  while ((m = re.exec(xml)) !== null) {
    var body = m[1].replace(/<[^>]+>/g, "");
    body = fqHtmlUnescape(body.trim());
    if (body) blocks.push(body);
  }
  if (blocks.length) return blocks.join("\n");
  var t = xml.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<style[\s\S]*?<\/style>/g, "");
  t = t.replace(/<[^>]+>/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  return fqHtmlUnescape(t);
}

// 取正文并解密
function fqFetchContent(java, bookId, itemId){
  var key = fqEnsureSessionKey(java);
  if (!key) return "正文获取失败：会话密钥无效";
  var resp = java.ajax(fqContentUrl(bookId, itemId));
  var j;
  try { j = JSON.parse(resp); } catch (e) { return "正文获取失败：" + String(resp); }
  var ch = (j && j.data && j.data[itemId]) || {};
  var code = ch.code;
  if (code !== undefined && code !== null && String(code) !== "0") {
    var msg = ch.message || "";
    var ci = String(ch.code_i32);
    if (msg.indexOf("LOCK") >= 0 || ci === "101045") {
      return "本章为番茄VIP/登录章节，暂无法免费阅读\n（需番茄账号登录后阅读）";
    }
    if (ci === "101002") {
      return "本章暂无法获取（番茄VIP章节或章节ID已失效）\n请求:book=" + bookId + " item=" + itemId + "\n若整本都如此，请删除本书重新添加以刷新目录";
    }
    return "正文获取失败：code=" + code + (msg ? " " + msg : "");
  }
  var c = ch.content || "";
  if (!c || c === "Invalid") return "";
  if (c.length < 32) return fqExtractText(c);
  // 判断是否为 base64 密文
  var looksB64 = true;
  var n = Math.min(80, c.length);
  for (var i = 0; i < n; i++) {
    var cc = c.charCodeAt(i);
    if (!((cc>=48&&cc<=57)||(cc>=65&&cc<=90)||(cc>=97&&cc<=122)||cc===43||cc===47||cc===61)) { looksB64 = false; break; }
  }
  if (!looksB64) return fqExtractText(c);
  try {
    var txt = fqDecryptContent(c, key);
    if (txt) return fqExtractText(txt);
  } catch (e) {}
  return c;
}

